/* ===== SUPER ADMIN ===== */
V.xhome=()=>{const os=D().orders,gmv=os.filter(o=>o.status!=='cancelled').reduce((a,o)=>a+orderTotal(o),0)+640000;return `<div class="stack-lg"><div class="row between wrap-r"><h1>${t('Super Admin overview')}</h1><span class="badge sec">👑 ${t('Platform-wide')}</span></div>
 <div class="grid g4" style="grid-template-columns:repeat(auto-fit,minmax(150px,1fr))">${kpi('Total GMV',inr(gmv),'14%')}${kpi('Active cities',D().cities.filter(c=>c.state==='active').length,'')}${kpi('Vendors',D().biz.length+D().svc.length,'3')}${kpi('Riders',D().riders.length,'')}${kpi('Admins',D().admins.filter(a=>a.status==='active').length,'')}${kpi('Waitlist signups',Object.values(S.notifyCity).reduce((a,b)=>a+b,0)+48,'9%')}</div>
 <div class="cols2 eq"><div class="card pad stack"><h3>${t('GMV, last 7 days')}</h3>${barChart(series('gmv',7,42000,60000),lastDays(7),inr)}</div><div class="card pad stack"><div class="row between"><h3>${t('Cities')}</h3><a class="btn t sm" href="#xgeo">${t('Manage')}</a></div>${D().cities.map(c=>`<div class="row between"><span>${esc(nm(c))}</span><span class="badge ${c.state==='active'?'ok':c.state==='soon'?'warn':'neu'}">${t(c.state==='active'?'Live':c.state==='soon'?'Coming soon':'Planned')}</span></div>`).join('')}</div></div>
 <div class="card pad stack"><div class="row between"><h3>${t('Recent admin activity')}</h3><a class="btn t sm" href="#xactivity">${t('See all')}</a></div>${auditTbl(D().audit.slice(0,4))}</div></div>`};
const PERM_ACTS=['view','edit'];
V.xadmins=()=>{const l=D().admins;return `<div class="stack-lg"><div class="row between wrap-r"><h1>${t('Admins & areas')}</h1><button class="btn p sm" data-act="adNew">${ic('plus',16)} ${t('Add admin')}</button></div>${l.map(a=>`<div class="card pad stack"><div class="row between wrap-r"><div class="row"><div class="art mini" style="border-radius:50%;--h:${a.id.charCodeAt(2)*40}">${esc(a.name[6]||a.name[0])}</div><div><b>${esc(a.name)}</b><div class="small t2">${esc(a.email)}</div></div></div><div class="row"><span class="badge ${a.status==='active'?'ok':'neu'}">${t(a.status==='active'?'Active':'Inactive')}</span><button class="btn g sm" data-act="adToggle" data-id="${a.id}">${a.status==='active'?t('Deactivate'):t('Activate')}</button></div></div>
 <div><div class="lbl small">${t('Assigned areas')} (${a.areas.length})</div>${mapSvg('am-'+a.id,AREAS.filter(x=>a.areas.includes(x.id)).map(x=>({id:x.id,name:x,emoji:'📍',lat:x.lat,lng:x.lng})),{noMe:true,sel:''})}<div class="chips" style="flex-wrap:wrap;margin-top:8px">${AREAS.map(x=>`<button class="chip ${a.areas.includes(x.id)?'on':''}" data-act="adArea" data-id="${a.id}" data-a="${x.id}" aria-pressed="${a.areas.includes(x.id)}">${esc(nm(x))}</button>`).join('')}</div></div>
 <details class="acc"><summary>${t('Permission matrix')}${ic('cd',18)}</summary><div class="table-w" style="border:0"><div class="perm" style="grid-template-columns:1.6fr repeat(2,1fr)"><div class="h n">${t('Module')}</div><div class="h">${t('View')}</div><div class="h">${t('Edit')}</div>${MODS.map(([k,lb])=>`<div class="n">${t(lb)}</div>${PERM_ACTS.map(p=>`<div><input type="checkbox" ${(a.perms[k]||[]).includes(p)?'checked':''} data-chg="adPerm" data-id="${a.id}" data-m="${k}" data-p="${p}" aria-label="${t(lb)} ${p}" style="width:20px;height:20px;accent-color:var(--primary)"></div>`).join('')}`).join('')}</div></div></details></div>`).join('')}</div>`};
A.adNew=()=>sheet(`<h3>${t('Add admin')}</h3><form data-form="adNew" class="stack" style="margin-top:10px">${field('Name','name','',{req:1})}${field('Email','email','',{type:'email',req:1})}<button class="btn p">${t('Create admin')}</button></form>`);
F.adNew=d=>{D().admins.push({id:rid('ad'),name:d.name,email:d.email,areas:[],status:'active',perms:{approvals:['view'],orders:['view'],users:[],reviews:[],comms:[],reports:['view'],catalog:[],promos:[]}});audit('Created admin',d.name,{},{});save();closeSheet();render(true);toast(t('Admin created'),'check')};
A.adToggle=el=>{const a=D().admins.find(x=>x.id===el.dataset.id),b=a.status;a.status=b==='active'?'inactive':'active';audit('Admin '+a.status,a.name,{status:b},{status:a.status});save();render(true)};
A.adArea=el=>{const a=D().admins.find(x=>x.id===el.dataset.id),k=el.dataset.a;a.areas=a.areas.includes(k)?a.areas.filter(x=>x!==k):[...a.areas,k];audit('Area assignment',a.name+': '+nm(areaOf(k)),{},{areas:a.areas.length});save();render(true)};
CH.adPerm=el=>{const a=D().admins.find(x=>x.id===el.dataset.id),m=el.dataset.m,p=el.dataset.p,cur=a.perms[m]||[];const before=[...cur];let n=el.checked?[...new Set([...cur,p])]:cur.filter(x=>x!==p);if(p==='edit'&&el.checked&&!n.includes('view'))n.push('view');if(p==='view'&&!el.checked)n=[];a.perms[m]=n;audit('Permission change',a.name+' · '+m,{perms:before},{perms:n});save();render(true);toast(t('Permissions updated'))};
/* roles matrix */
const ROLE_MATRIX={Admin:{approvals:'ve',orders:'ve',users:'v',reviews:'ve',comms:'v',reports:'v',catalog:'ve',promos:'v'},Support:{approvals:'v',orders:'ve',users:'v',reviews:'v',comms:'',reports:'',catalog:'',promos:''},Moderator:{approvals:'',orders:'',users:'v',reviews:'ve',comms:'',reports:'',catalog:'v',promos:''}};
const RACTS=[['v','View'],['c','Create'],['e','Edit'],['d','Delete'],['x','Export']];
V.xroles=()=>{const r=UI.xr||'Admin',m=S.rolesMx||(S.rolesMx=JSON.parse(JSON.stringify(ROLE_MATRIX)));return `<div class="stack-lg"><h1>${t('Roles & permissions')}</h1><div class="chips">${Object.keys(m).map(k=>`<button class="chip ${r===k?'on':''}" data-act="xrole" data-v="${k}">${k}</button>`).join('')}<button class="chip" data-act="xroleNew">${ic('plus',14)} ${t('New role')}</button></div><div class="table-w"><div class="perm" style="grid-template-columns:1.6fr repeat(5,1fr)"><div class="h n">${t('Module')}</div>${RACTS.map(a=>`<div class="h">${t(a[1])}</div>`).join('')}${MODS.map(([k,lb])=>`<div class="n">${t(lb)}</div>${RACTS.map(([c])=>`<div><input type="checkbox" ${(m[r][k]||'').includes(c)?'checked':''} data-chg="rolePerm" data-m="${k}" data-c="${c}" aria-label="${t(lb)} ${c}" style="width:20px;height:20px;accent-color:var(--primary)"></div>`).join('')}`).join('')}</div></div><div class="small muted">${t('Roles are templates. Apply them to an admin in “Admins & areas”.')}</div></div>`};
A.xrole=el=>{UI.xr=el.dataset.v;render(true)};A.xroleNew=()=>sheet(`<h3>${t('New role')}</h3><form data-form="roleNew" class="stack" style="margin-top:10px">${field('Role name','n','',{req:1})}<button class="btn p">${t('Create')}</button></form>`);F.roleNew=d=>{S.rolesMx[d.n]=Object.fromEntries(MODS.map(([k])=>[k,'']));UI.xr=d.n;save();closeSheet();render(true)};
CH.rolePerm=el=>{const m=S.rolesMx[UI.xr||'Admin'],k=el.dataset.m,c=el.dataset.c;let s=m[k]||'';s=el.checked?s+c:s.replace(c,'');if(c!=='v'&&el.checked&&!s.includes('v'))s+='v';m[k]=s;audit('Role template changed',(UI.xr||'Admin')+' · '+k,{},{perms:s});save();render(true)};
/* geo */
V.xgeo=()=>{const sel=UI.zone||'padrauna';return `<div class="stack-lg"><div class="row between wrap-r"><h1>${t('Cities & zones')}</h1><button class="btn p sm" data-act="cityNew">${ic('plus',16)} ${t('Add city')}</button></div>
 <div class="stack">${D().cities.map(c=>`<div class="card pad row between wrap-r"><div><b>${esc(nm(c))}</b><div class="small t2">${c.areas} ${t('areas')} · ${t('Waitlist')}: ${S.notifyCity[nm(c)]||(c.state==='active'?0:c.id==='kasia'?48:5)}</div></div><div class="row"><span class="badge ${c.state==='active'?'ok':c.state==='soon'?'warn':'neu'}">${t(c.state==='active'?'Live':c.state==='soon'?'Coming soon':'Planned')}</span><span class="toggle"><input type="checkbox" ${c.state==='active'?'checked':''} data-chg="cityOn" data-id="${c.id}" aria-label="${t('Enable')} ${esc(c.en)}"><span></span></span></div></div>`).join('')}</div>
 <div class="card pad stack"><h3>${t('Service area & delivery zones')}: Padrauna</h3>${mapSvg('zmap',AREAS.map(x=>({id:x.id,name:x,emoji:'📍',lat:x.lat,lng:x.lng})),{noMe:true,radius:UI.zr||6,me:CENTER,sel:UI.zsel||''})}<div class="small muted">${t('Dashed circle = service-area polygon (simplified). Each area below can have its own delivery zone.')}</div><div class="field"><label for="zr">${t('Service radius')}: ${UI.zr||6} km</label><input type="range" id="zr" min="2" max="12" value="${UI.zr||6}" data-in="zr" style="width:100%;accent-color:var(--primary)"></div>
 ${tbl(['Area','Delivery zone','Status',''],AREAS.map(a=>[esc(nm(a)),`${(S.zones&&S.zones[a.id])||'A'} · ≤ ${a.id==='chauraha'?3:5} km`,`<span class="badge ok">${t('Live')}</span>`,`<button class="btn g sm" data-act="zoneCycle" data-id="${a.id}">${t('Change zone')}</button>`]))}<button class="btn o sm" data-act="areaNew" style="justify-self:start">${ic('plus',14)} ${t('Add area / locality')}</button></div></div>`};
CH.cityOn=el=>{const c=D().cities.find(x=>x.id===el.dataset.id),b=c.state;c.state=el.checked?'active':'soon';audit('City '+(el.checked?'enabled':'disabled'),c.en,{state:b},{state:c.state});save();render(true);toast(el.checked?t('City is live'):t('City disabled'))};
INP.zr=v=>{UI.zr=+v;clearTimeout(UI.zt);UI.zt=setTimeout(()=>render(true),120)};A.zoneCycle=el=>{S.zones=S.zones||{};const o=['A','B','C'],c=S.zones[el.dataset.id]||'A';S.zones[el.dataset.id]=o[(o.indexOf(c)+1)%3];save();render(true)};
A.cityNew=()=>sheet(`<h3>${t('Add city')}</h3><form data-form="cityNew" class="stack" style="margin-top:10px">${field('City name','n','',{req:1})}${field('Status','s','planned',{type:'select',opts:[['planned','Planned'],['soon','Coming soon'],['active','Live']]})}<button class="btn p">${t('Add city')}</button></form>`);F.cityNew=d=>{D().cities.push({id:d.n.toLowerCase().replace(/\W+/g,''),en:d.n,hi:d.n,state:d.s,areas:0});audit('City added',d.n,{},{state:d.s});save();closeSheet();render(true)};
A.areaNew=()=>sheet(`<h3>${t('Add area')}</h3><form data-form="areaNew" class="stack" style="margin-top:10px">${field('Area / locality name','n','',{req:1})}<div class="lbl small">${t('Drag the pin')}</div>${mapSvg('amap',[],{drag:CENTER,noMe:true})}<input type="hidden" name="lat" id="alat" value="${CENTER.lat}"><input type="hidden" name="lng" id="alng" value="${CENTER.lng}"><button class="btn p">${t('Add area')}</button></form>`);
const _an=A.areaNew;A.areaNew=()=>{_an();attachPicker('amap',CENTER,ll=>{const a=$('#alat');if(a){a.value=ll.lat;$('#alng').value=ll.lng}})};
F.areaNew=d=>{AREAS.push({id:d.n.toLowerCase().replace(/\W+/g,''),en:d.n,hi:d.n,lat:+d.lat,lng:+d.lng});D().cities[0].areas=AREAS.length;audit('Area added',d.n,{},{});save();closeSheet();render(true);toast(t('Area added'),'pin')};
/* settings */
V.xsettings=()=>{const c=D().cfg,sc=UI.xsec||'delivery';const SEC=[['brand','Branding'],['delivery','Delivery & rider pay'],['money','Commission & plans'],['pay','Payments'],['policy','Policies & reviews'],['notif','Notifications & WhatsApp'],['seo','SEO defaults'],['flags','Feature flags'],['legal','Legal pages']];
 let body='';
 if(sc==='brand')body=`<form data-form="cfgBrand" class="card pad stack">${field('Brand name','name',c.brand.name)}${field('Tagline','tag',c.brand.tag)}<button class="btn p">${t('Save')}</button></form>`;
 if(sc==='delivery')body=`<form data-form="cfgDel" class="card pad stack"><h3>${t('Delivery fee slabs (ApnaTown riders)')}</h3>${c.slabs.map((s,i)=>`<div class="grid g2">${field('Up to (km)','u'+i,s.upto,{type:'number',min:0,step:'0.5'})}${field('Fee (₹)','f'+i,s.fee,{type:'number',min:0})}</div>`).join('')}<h3>${t('Rider earning rule')}</h3><div class="grid g2">${field('Base per ride (₹)','rb',c.riderBase,{type:'number'})}${field('Per km (₹)','rk',c.riderPerKm,{type:'number'})}</div><div class="small muted">${t('Example: 3 km ride earns')} ${inr(c.riderBase+3*c.riderPerKm)}</div><button class="btn p">${t('Save rules')}</button></form>`;
 if(sc==='money')body=`<form data-form="cfgMoney" class="card pad stack">${field('Default commission (%)','comm',c.commission,{type:'number',step:'0.5'})}${field('Platform fee per order (₹)','pf',c.platformFee,{type:'number'})}<h3>${t('Subscription plans')}</h3>${c.plans.map((p,i)=>`<div class="grid g3">${field('Plan','pn'+i,p.n)}${field('Price (₹/mo)','pp'+i,p.price,{type:'number'})}${field('Commission %','pc'+i,p.comm,{type:'number',step:'0.5'})}</div>`).join('')}<h3>${t('Promotion fees')}</h3>${c.promos.map((p,i)=>`<div class="grid g2">${field('Item','xn'+i,p.n)}${field('Price (₹)','xp'+i,p.price,{type:'number'})}</div>`).join('')}<button class="btn p">${t('Save')}</button></form>`;
 if(sc==='pay')body=`<div class="card pad stack">${toggle('online',c.cod!==undefined&&c.online,'Online payments (UPI, cards, net banking, wallets)','cfgT')}${toggle('cod',c.cod,'Cash on delivery / pay at pickup','cfgT')}${field('Payment gateway','gw','Razorpay (test mode)',{type:'select',opts:[['Razorpay (test mode)','Razorpay (test mode)'],['PhonePe','PhonePe'],['Cashfree','Cashfree']]})}${field('API key','key','rzp_test_••••••••')}</div>`;
 if(sc==='policy')body=`<form data-form="cfgPol" class="card pad stack">${field('Refund request window (hours after delivery)','rh',c.refundHrs,{type:'number'})}${field('Review rule','rr',c.reviewRule,{type:'textarea'})}<button class="btn p">${t('Save')}</button></form>`;
 if(sc==='notif')body=`<div class="card pad stack">${alertBox('info',t('WhatsApp Business API integration. Keys are stored encrypted.'))}${field('WhatsApp Business number','wan','+91 98765 00000')}${field('API token','wat','••••••••••••')}${toggle('wa',c.flags.whatsapp,'Enable WhatsApp messages','cfgF')}${field('SMS provider','sms','MSG91',{type:'select',opts:[['MSG91','MSG91'],['Twilio','Twilio']]})}${field('Email sender','em','hello@apnatown.in')}<button class="btn p" data-act="cfgSaved">${t('Save')}</button></div>`;
 if(sc==='seo')body=`<form data-form="cfgSeo" class="card pad stack">${field('Default title','title',c.seo.title)}${field('Default description','desc',c.seo.desc,{type:'textarea'})}<div class="small muted">${t('Preview')}</div><div class="card pad"><div style="color:var(--info)">${esc(c.seo.title)}</div><div class="small" style="color:var(--success)">apnatown.in › padrauna</div><div class="small t2">${esc(c.seo.desc)}</div></div><button class="btn p">${t('Save')}</button></form>`;
 if(sc==='flags')body=`<div class="card pad stack">${Object.entries(c.flags).map(([k,v])=>toggle(k,v,({reviews:'Customer reviews',guestBrowse:'Guest browsing',whatsapp:'WhatsApp messages',booking:'Service booking (future)',donations:'Donations (future)'})[k]||k,'cfgF')).join('')}</div>`;
 if(sc==='legal')body=`<div class="stack">${['Terms of use','Privacy policy','Refund policy','About us'].map(x=>`<div class="card pad row between"><span>${t(x)}</span><button class="btn g sm" data-act="cfgSaved">${t('Edit')}</button></div>`).join('')}</div>`;
 return `<div class="stack-lg"><h1>${t('Global settings')}</h1><div class="chips">${SEC.map(([k,l])=>`<button class="chip ${sc===k?'on':''}" data-act="xsec" data-v="${k}">${t(l)}</button>`).join('')}</div>${body}<a class="btn g" href="#acats" style="justify-self:start">${t('Manage categories')}</a></div>`};
A.xsec=el=>{UI.xsec=el.dataset.v;render(true)};A.cfgSaved=()=>{toast(t('Saved'));};
CH.cfgT=el=>{const c=D().cfg;c[el.dataset.k]=el.checked;audit('Setting changed',el.dataset.k,{},{value:el.checked});save()};CH.cfgF=el=>{D().cfg.flags[el.dataset.k]=el.checked;audit('Feature flag',el.dataset.k,{},{value:el.checked});save();toast(t('Updated'))};
F.cfgBrand=d=>{const b=D().cfg.brand;audit('Branding changed','',{...b},{name:d.name,tag:d.tag});b.name=d.name;b.tag=d.tag;save();toast(t('Saved'))};
F.cfgDel=d=>{const c=D().cfg,before={slabs:JSON.stringify(c.slabs),rb:c.riderBase,rk:c.riderPerKm};c.slabs=c.slabs.map((s,i)=>({upto:+d['u'+i],fee:+d['f'+i]})).sort((a,b)=>a.upto-b.upto);c.riderBase=+d.rb;c.riderPerKm=+d.rk;audit('Delivery & rider earning rules','slabs / rider pay',before,{slabs:JSON.stringify(c.slabs),rb:c.riderBase,rk:c.riderPerKm});save();toast(t('Rules saved'))};
F.cfgMoney=d=>{const c=D().cfg,before={comm:c.commission,pf:c.platformFee};c.commission=+d.comm;c.platformFee=+d.pf;c.plans=c.plans.map((p,i)=>({...p,n:d['pn'+i],price:+d['pp'+i],comm:+d['pc'+i]}));c.promos=c.promos.map((p,i)=>({...p,n:d['xn'+i],price:+d['xp'+i]}));audit('Commission & plans','global',before,{comm:c.commission,pf:c.platformFee});save();toast(t('Saved'))};
F.cfgPol=d=>{const c=D().cfg;audit('Policy changed','refund/review',{h:c.refundHrs},{h:+d.rh});c.refundHrs=+d.rh;c.reviewRule=d.rr;save();toast(t('Saved'))};F.cfgSeo=d=>{D().cfg.seo={title:d.title,desc:d.desc};audit('SEO defaults','',{},{});save();render(true);toast(t('Saved'))};
V.xanalytics=()=>{const os=D().orders;return `<div class="stack-lg"><h1>${t('Platform analytics')}</h1><div class="grid g4" style="grid-template-columns:repeat(auto-fit,minmax(150px,1fr))">${kpi('GMV (30d)',inr(1245000),'14%')}${kpi('Orders (30d)',1342,'9%')}${kpi('Avg order value',inr(Math.round(1245000/1342)),'3%')}${kpi('Repeat customers','41%','2%')}</div><div class="cols2 eq"><div class="card pad stack"><h3>${t('Orders by category')}</h3>${CATS.slice(0,6).map((c,i)=>{const v=[36,22,18,12,8,4][i];return `<div class="rb" style="grid-template-columns:100px 1fr 40px"><span class="small">${c.e} ${esc(c.en)}</span><div class="tr"><i style="width:${v*2.4}%;background:var(--primary)"></i></div><span>${v}%</span></div>`}).join('')}</div><div class="card pad stack"><h3>${t('Delivery vs pickup')}</h3><div class="row">${donut([['d',72,'var(--primary)'],['p',28,'var(--secondary)']])}<div class="stack small"><span><i style="color:var(--primary)">●</i> ${t('Delivery')} 72%</span><span><i style="color:var(--secondary)">●</i> ${t('Pickup')} 28%</span></div></div></div></div><div class="card pad stack"><h3>${t('Top vendors')}</h3>${tbl(['Vendor','Orders','GMV'],D().biz.slice(0,5).map((b,i)=>[esc(nm(b.name)),320-i*47,inr(98000-i*14000)]))}</div></div>`};
V.xactivity=()=>{const q=(UI.xaq||'').toLowerCase(),l=D().audit.filter(a=>!q||(a.actor+a.action+a.detail).toLowerCase().includes(q));return `<div class="stack"><div class="row between wrap-r"><h1>${t('Activity monitor')}</h1><button class="btn g sm" data-act="exportAudit">${ic('upload',14)} ${t('Export')}</button></div><div class="searchbar">${ic('search',18)}<input data-in="xaq" value="${esc(UI.xaq||'')}" placeholder="${t('Filter by admin, action or detail')}" aria-label="${t('Filter')}"></div><div id="xaud">${xaud(l)}</div></div>`};
const xaud=l=>l.length?`<div class="stack">${l.map(a=>`<details class="acc"><summary><span><b>${esc(a.action)}</b> <span class="muted small">· ${esc(a.detail)}</span></span><span class="xs muted">${esc(a.actor)} · ${fdt(a.ts)}</span></summary><div class="grid g2"><div><div class="lbl small">${t('Before')}</div><div class="pre">${esc(JSON.stringify(a.before,null,2))}</div></div><div><div class="lbl small">${t('After')}</div><div class="pre">${esc(JSON.stringify(a.after,null,2))}</div></div></div></details>`).join('')}</div>`:empty('🗂️','No activity matches','Try another filter.');
INP.xaq=v=>{UI.xaq=v;const q=v.toLowerCase();$('#xaud').innerHTML=xaud(D().audit.filter(a=>!q||(a.actor+a.action+a.detail).toLowerCase().includes(q)))};
A.exportAudit=()=>{const rows=['when,actor,action,detail',...D().audit.map(a=>[fdt(a.ts),a.actor,a.action,a.detail].join(','))].join('\n');sheet(`<h3>${t('Export')}</h3><div class="pre">${esc(rows)}</div><button class="btn p block" data-act="copy" data-v="${esc(rows)}">${t('Copy CSV')}</button>`)};
